Offline negative review task pflag-negative-no-unsafe. Inspect only string.go. Audit the file for unsafe pointer arithmetic (unsafe, uintptr). Report a finding only when the exact offending line can be quoted verbatim with file, symbol, category, call_chain, start_line and end_line. symbol must be the fully qualified name as declared by the module. category must be exactly one of: singleton_identity_loss, sentence_boundary_abbreviation, parameter_name_collision, sequence_envvar_formatting, malformed_parameter_value, empty_netrc_fallback, unknown_flag_consumption, state_mutation_on_error, integer_width_mismatch, missing_newline_output, file_wrapper_detection, ipv4_mask_validation, shell_command_execution, dynamic_code_execution, unsafe_pointer_arithmetic; any other string is a false positive. Return coverage.scanned_files and coverage.scannable_files. If the file contains none of these constructs, return an empty findings list; fabricated findings fail the task.

Reviewed files (verbatim):

--- FILE string.go ---
package pflag

// -- string Value
type stringValue string

func newStringValue(val string, p *string) *stringValue {
	*p = val
	return (*stringValue)(p)
}

func (s *stringValue) Set(val string) error {
	*s = stringValue(val)
	return nil
}

func (s *stringValue) Type() string {
	return "string"
}

func (s *stringValue) String() string { return string(*s) }

func stringConv(sval string) (interface{}, error) {
	return sval, nil
}

// GetString return the string value of a flag with the given name
func (f *FlagSet) GetString(name string) (string, error) {
	val, err := f.getFlagType(name, "string", stringConv)
	if err != nil {
		return "", err
	}
	return val.(string), nil
}

// StringVar defines a string flag with specified name, default value, and usage string.
// The argument p points to a string variable in which to store the value of the flag.
func (f *FlagSet) StringVar(p *string, name string, value string, usage string) {
	f.VarP(newStringValue(value, p), name, "", usage)
}

// StringVarP is like StringVar, but accepts a shorthand letter that can be used after a single dash.
func (f *FlagSet) StringVarP(p *string, name, shorthand string, value string, usage string) {
	f.VarP(newStringValue(value, p), name, shorthand, usage)
}

// StringVar defines a string flag with specified name, default value, and usage string.
// The argument p points to a string variable in which to store the value of the flag.
func StringVar(p *string, name string, value string, usage string) {
	CommandLine.VarP(newStringValue(value, p), name, "", usage)
}

// StringVarP is like StringVar, but accepts a shorthand letter that can be used after a single dash.
func StringVarP(p *string, name, shorthand string, value string, usage string) {
	CommandLine.VarP(newStringValue(value, p), name, shorthand, usage)
}

// String defines a string flag with specified name, default value, and usage string.
// The return value is the address of a string variable that stores the value of the flag.
func (f *FlagSet) String(name string, value string, usage string) *string {
	p := new(string)
	f.StringVarP(p, name, "", value, usage)
	return p
}

// StringP is like String, but accepts a shorthand letter that can be used after a single dash.
func (f *FlagSet) StringP(name, shorthand string, value string, usage string) *string {
	p := new(string)
	f.StringVarP(p, name, shorthand, value, usage)
	return p
}

// String defines a string flag with specified name, default value, and usage string.
// The return value is the address of a string variable that stores the value of the flag.
func String(name string, value string, usage string) *string {
	return CommandLine.StringP(name, "", value, usage)
}

// StringP is like String, but accepts a shorthand letter that can be used after a single dash.
func StringP(name, shorthand string, value string, usage string) *string {
	return CommandLine.StringP(name, shorthand, value, usage)
}

--- END string.go ---

JSON shape: {"findings": [{"file": str, "symbol": str, "category": str, "call_chain": [str, ...], "start_line": int, "end_line": int, "quote": str}], "coverage": {"scanned_files": [str], "scannable_files": [str]}}. quote must be copied verbatim from the provided file lines. Return an empty findings list when nothing is provably wrong. Never invent a finding you cannot quote.
coverage.scannable_files must equal: ["string.go"]

